#include "biunique-code-dictionary.h"
#include <charconv>
#include <stdexcept>
namespace code_dictionary {void Dictionary::insert(std::int64_t code,std::string name){auto c=by_code_.find(code);auto n=by_name_.find(name);if(c!=by_code_.end()||n!=by_name_.end()){if(c!=by_code_.end()&&n!=by_name_.end()&&c->second==name&&n->second==code)return;throw std::invalid_argument("collision");}by_code_.emplace(code,name);by_name_.emplace(std::move(name),code);}std::int64_t Dictionary::parse(const std::string& text)const{if(text.empty())throw std::invalid_argument("code");std::size_t start=text[0]=='+'?1:0;if(start==text.size())throw std::invalid_argument("code");std::int64_t value=0;auto r=std::from_chars(text.data()+static_cast<std::ptrdiff_t>(start),text.data()+text.size(),value);if(r.ec!=std::errc{}||r.ptr!=text.data()+text.size())throw std::invalid_argument("code");return value;}std::string Dictionary::format(std::int64_t code)const{auto it=by_code_.find(code);return it==by_code_.end()?std::to_string(code):it->second;}std::size_t Dictionary::size()const noexcept{return by_code_.size();}}
